We should be able to do the bulk of prefix parsing, and state management directly in this function (I don't mind having a helper function for prefix parsing, but I think it can be shorter than `checkPrefix` is now).

See below rough example that shows both the prefix detection and also state transition to tool calling. It can probably also be simplified.

Note: this doesn't handle the empty prefix case. In that case, we'll probably need to instead determine `p.found` or the state transition to tool call parsing based on incremental json parsing (e.g. seeing `{` or if the json parser is making progress)

```go
// overlap returns the index in s where prefix begins,
// even if prefix is incomplete, otherwise it returns -1
// (I think you have this already)
func overlap(s, prefix string) int {
	max := len(prefix)
	if len(s) < max {
		max = len(s)
	}
	for i := max; i > 0; i-- {
		if strings.HasSuffix(s, prefix[:i]) {
			return len(s) - i // start position of the overlap
		}
	}
	return -1
}

func (p *Parser) Add(s string) (tools []api.ToolCall, content string, error) {
    if len(s) == 0 {
        reutrn nil, ""
    }

    p.sb.Writestring(s)

    for {
        // alternatively use the states
        if !p.found {
            b := p.buf.String()
            idx := strings.Index(b, p.prefix)
            if idx == -1 {
                // No full prefix yet – see if the end of the buffer *might* be its start.
                keep := overlap(b, p.prefix)
                emit := len(b) - keep
                if emit > 0 {
                    content := b[:emit]
                    p.buf.Reset()
                    p.buf.WriteString(b[emit:])
                    return nil, content, nil
                }
    
                // continue waiting for rest of prefix
                return nil, "", nil
            }
    
            content = b[:idx]                      // stream everything before it
            p.buf.Reset()
            p.buf.WriteString(b[idx+len(p.prefix):])            // keep only after the prefix
            p.found = true
            continue
        }

        // tool calling code you have below, but we shouldn't need any more state transitions
        // we only need to continue buffering and emitting tool calls as they parse
    }
}
